#!/usr/bin/env bash
set -e
cd "$W"
SEC=$(openssl rand -hex 32)
cat > verify.py <<EOF
import sys, base64, json, hmac, hashlib
SECRET = bytes.fromhex("$SEC")

def b64d(s):
    s = s + '=' * (-len(s) % 4)
    return base64.urlsafe_b64decode(s.encode())

def main():
    try:
        tok = open(sys.argv[1]).read().strip()
        h, p, s = tok.split('.')
        hdr = json.loads(b64d(h))
        pl = json.loads(b64d(p))
    except Exception:
        print('DENIED')
        return
    alg = hdr.get('alg')
    ok = False
    if alg == 'none':
        ok = (s == '')
    elif alg == 'HS256':
        want = base64.urlsafe_b64encode(
            hmac.new(SECRET, (h + '.' + p).encode(), hashlib.sha256).digest()
        ).rstrip(b'=').decode()
        ok = (s == want)
    if ok and pl.get('role') == 'admin':
        print('GRANTED', pl.get('sub', '?'))
    else:
        print('DENIED')

main()
EOF

